  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→  Workspace,
 65→} from "@/lib/types";
 66→import { sfxTool, sfxDone, sfxError, sfxQuestion, sfxBegin, sfxSend } from "@/lib/sfx";
 67→
 68→/** Connect to the WS server on the same host the page was loaded from. */
 69→const WS_URL =
 70→  typeof window !== "undefined"
 71→    ? `ws://${window.location.hostname}:9900/browser`
 72→    : "ws://localhost:9900/browser";
 73→
 74→/** Per-agent client state. */
 75→export interface AgentClientState {
 76→  status: AgentStatus;
 77→  messages: ChatMessage[];
 78→  /** Raw Claude NDJSON messages for debug view. */
 79→  rawMessages: ClaudeMessage[];
 80→  label: string;
 81→  tmuxSession: string | null;
 82→  createdAt: number;
 83→}
 84→
 85→/**
 86→ * Extract displayable text from a Claude assistant message.
 87→ * Content blocks may be text, tool_use, or tool_result — each is
 88→ * handled defensively since the array structure can vary.
 89→ */
 90→function extractText(msg: ClaudeAssistant): string {
 91→  const blocks = msg.message?.content;
 92→  if (!blocks || !Array.isArray(blocks)) return "";
 93→  return blocks
 94→    .map((b) => {
 95→      if (b.type === "text") return b.text;
 96→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 97→      if (b.type === "tool_result") {
 98→        const c = (b as { content?: unknown }).content;
 99→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
100→      }
101→      return "";
102→    })
103→    .filter(Boolean)
104→    .join("\n");
105→}
106→
107→/** Module-level counter for generating unique message IDs. */
108→let msgCounter = 0;
109→function nextId() {
110→  return `msg-${Date.now()}-${++msgCounter}`;
111→}
112→
113→/**
114→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
115→ * Used both for live messages and for replaying message_history.
116→ */
117→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
118→  if (relayMsg.type === "relay") {
119→    const msg = relayMsg.message;
120→
121→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
122→      const init = msg as ClaudeSystemInit;
123→      return {
124→        id: nextId(),
125→        role: "system",
126→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
127→        timestamp: Date.now(),
128→      };
129→    }
130→
131→    if (msg.type === "user") {
132→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
133→      // Only render human-typed user messages (string content).
134→      // CLI tool_result messages have array content — these are internal
135→      // protocol messages and are only visible in the raw message viewer.
136→      if (typeof rawContent !== "string") return null;
137→      if (!rawContent.trim()) return null;
138→      return {
139→        id: nextId(),
140→        role: "user",
141→        content: rawContent,
142→        timestamp: Date.now(),
143→      };
144→    }
145→
146→    if (msg.type === "assistant") {
147→      const assistant = msg as ClaudeAssistant;
148→      const text = extractText(assistant);
149→      if (!text) return null;
150→
151→      const blocks = assistant.message?.content ?? [];
152→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
153→
154→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
155→      const resultMap = new Map<string, string>();
156→      for (const b of blocks) {
157→        if (b.type === "tool_result") {
158→          const tr = b as { tool_use_id?: string; content?: unknown };
159→          if (tr.tool_use_id) {
160→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
161→            const firstLine = raw.split("\n")[0];
162→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
163→          }
164→        }
165→      }
166→
167→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
168→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
169→      // DiffViewer can render syntax-highlighted before/after diffs. Other
170→      // tools only keep the name and result preview to avoid carrying
171→      // unnecessary data (e.g. Read file contents, Bash output).
172→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
173→      const toolCalls: ToolCallInfo[] = blocks
174→        .filter((b) => b.type === "tool_use")
175→        .map((b) => {
176→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
177→          const info: ToolCallInfo = {
178→            name: tu.name,
179→            toolUseId: tu.id,
180→            resultPreview: resultMap.get(tu.id),
181→          };
182→          if (DIFF_TOOLS.has(tu.name)) {
183→            info.input = tu.input;
184→          }
185→          return info;
186→        });
187→      const isToolOnly = !hasText && toolCalls.length > 0;
188→
189→      return {
190→        id: nextId(),
191→        role: "assistant",
192→        content: text,
193→        timestamp: Date.now(),
194→        toolCalls,
195→        isToolOnly,
196→      };
197→    }
198→
199→    if (msg.type === "result") {
200→      const result = msg as ClaudeResult;
201→      const summary = result.is_error
202→        ? `Error: ${result.error}`
203→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
204→      return {
205→        id: nextId(),
206→        role: "system",
207→        content: summary,
208→        timestamp: Date.now(),
209→      };
210→    }
211→
212→    if (msg.type === "control_request") {
213→      const cr = msg as ClaudeControlRequest;
214→
215→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
216→      if (cr.request.tool_name === "AskUserQuestion") {
217→        const input = cr.request.input as { questions?: UserQuestion[] };
218→        const questions = Array.isArray(input.questions) ? input.questions : [];
219→        return {
220→          id: nextId(),
221→          role: "system",
222→          content: "Question from Claude",
223→          timestamp: Date.now(),
224→          userQuestion: {
225→            requestId: cr.request_id,
226→            questions,
227→          },
228→        };
229→      }
230→
231→      return {
232→        id: nextId(),
233→        role: "system",
234→        content: `Tool approval requested: ${cr.request.tool_name}`,
235→        timestamp: Date.now(),
236→        controlRequest: {
237→          id: cr.request_id,
238→          tool_name: cr.request.tool_name,
239→          input: cr.request.input,
240→          description: cr.request.description,
241→        },
242→      };
243→    }
244→  }
245→
246→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
247→    return {
248→      id: nextId(),
249→      role: "system",
250→      content: `Error: ${relayMsg.error}`,
251→      timestamp: Date.now(),
252→    };
253→  }
254→
255→  return null;
256→}
257→
258→/** Console logger with [thos] prefix for easy filtering. */
259→function log(...args: unknown[]) {
260→  console.log("[thos-ws]", ...args);
261→}
262→
263→export function useWebSocket() {
264→  const wsRef = useRef<WebSocket | null>(null);
265→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
266→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
267→  const closingRef = useRef(false);
268→  const [connected, setConnected] = useState(false);
269→  /** True once we've received the initial agent_list from the server. */
270→  const [initialLoadDone, setInitialLoadDone] = useState(false);
271→
272→  // Multi-agent state
273→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
274→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
275→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
276→
277→  // Task state
278→  const [tasks, setTasks] = useState<Task[]>([]);
279→
280→  // Workspace state
281→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
282→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
283→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
284→
285→  // Per-agent deduplication: track count of processed messages per agent
286→  // to avoid duplicating messages already in local state during history replay.
287→  const processedCountRef = useRef<Map<string, number>>(new Map());
288→
289→  // Track which agents have had their history loaded (lazy loading).
290→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
291→
292→  /** Immutably update a single agent's state in the Map. */
293→  const updateAgent = useCallback(
294→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
295→      setAgents((prev) => {
296→        const existing = prev.get(agentId);
297→        if (!existing) return prev;
298→        const next = new Map(prev);
299→        next.set(agentId, updater(existing));
300→        return next;
301→      });
302→    },
303→    []
304→  );
305→
306→  const connect = useCallback(() => {
307→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
308→    if (wsRef.current) {
309→      wsRef.current.close();
310→      wsRef.current = null;
311→    }
312→
313→    // Reset dedup counts on new connection — server will send fresh history
314→    processedCountRef.current.clear();
315→    setInitialLoadDone(false);
316→    setLoadedAgents(new Set());
317→
318→    log("connecting to", WS_URL);
319→    const ws = new WebSocket(WS_URL);
320→    wsRef.current = ws;
321→
322→    ws.onopen = () => {
323→      log("connected");
324→      setConnected(true);
325→    };
326→
327→    ws.onclose = () => {
328→      log("disconnected, closingRef =", closingRef.current);
329→      setConnected(false);
330→      wsRef.current = null;
331→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
332→      if (closingRef.current) return;
333→      // Reconnection guard: clear any existing timer before scheduling
334→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
335→      log("scheduling reconnect in 2s");
336→      reconnectTimer.current = setTimeout(() => connect(), 2000);
337→    };
338→
339→    ws.onerror = (e) => {
340→      log("error", e);
341→      // onclose will fire after onerror, which triggers reconnect
342→    };
343→
344→    ws.onmessage = (event) => {
345→      let data: ServerMessage;
346→      try {
347→        data = JSON.parse(event.data as string);
348→      } catch {
349→        return;
350→      }
351→
352→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
353→
354→      // ── workspace_list: full workspace list from server ──
355→      if (data.type === "workspace_list") {
356→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
357→        log("workspace_list:", wsList.length, "workspaces");
358→        setWorkspaces(wsList);
359→        return;
360→      }
361→
362→      // ── directory_listing: response to browse_directory ──
363→      if (data.type === "directory_listing") {
364→        const listing = data as { path: string; entries: DirectoryEntry[] };
365→        log("directory_listing:", listing.path, listing.entries.length, "entries");
366→        setDirectoryListing({ path: listing.path, entries: listing.entries });
367→        return;
368→      }
369→
370→      // ── task_list: full task list from server ──
371→      if (data.type === "task_list") {
372→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
373→        setTasks((data as ServerTaskList).tasks);
374→        return;
375→      }
376→
377→      // ── task_updated: single task changed ──
378→      if (data.type === "task_updated") {
379→        const updated = (data as ServerTaskUpdated).task;
380→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
381→        return;
382→      }
383→
384→      // ── task_deleted: remove task ──
385→      if (data.type === "task_deleted") {
386→        const deletedId = (data as ServerTaskDeleted).taskId;
387→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
388→        return;
389→      }
390→
391→      // ── message_history: replay full history from server ──
392→      if (data.type === "message_history") {
393→        const historyMsg = data as ServerMessageHistory;
394→        const agentId = historyMsg.agentId;
395→        const serverMessages = historyMsg.messages;
396→        log("message_history:", agentId, serverMessages.length, "raw msgs");
397→
398→        // Convert all server messages to ChatMessages + extract raw Claude messages
399→        const chatMessages: ChatMessage[] = [];
400→        const rawMessages: ClaudeMessage[] = [];
401→        for (const sm of serverMessages) {
402→          if (sm.type === "relay") {
403→            rawMessages.push(sm.message);
404→          }
405→          const cm = relayChatMessage(agentId, sm);
406→          if (cm) chatMessages.push(cm);
407→        }
408→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
409→
410→        // Always replace local messages with server history (source of truth).
411→        setAgents((prev) => {
412→          const existing = prev.get(agentId);
413→          if (!existing) {
414→            log("message_history:", agentId, "agent not in map yet, creating");
415→            const next = new Map(prev);
416→            next.set(agentId, {
417→              status: "idle",
418→              messages: chatMessages,
419→              rawMessages,
420→              label: "",
421→              tmuxSession: null,
422→              createdAt: 0,
423→            });
424→            return next;
425→          }
426→          const next = new Map(prev);
427→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
428→          return next;
429→        });
430→
431→        processedCountRef.current.set(agentId, chatMessages.length);
432→        setLoadedAgents((prev) => {
433→          if (prev.has(agentId)) return prev;
434→          const next = new Set(prev);
435→          next.add(agentId);
436→          return next;
437→        });
438→        return;
439→      }
440→
441→      // ── history_cleared: wipe local messages for this agent ──
442→      if (data.type === "history_cleared") {
443→        updateAgent(data.agentId, (prev) => ({
444→          ...prev,
445→          messages: [],
446→          rawMessages: [],
447→        }));
448→        processedCountRef.current.set(data.agentId, 0);
449→        return;
450→      }
451→
452→      // ── cli_disconnected: show system message ──
453→      if (data.type === "cli_disconnected") {
454→        updateAgent(data.agentId, (prev) => ({
455→          ...prev,
456→          messages: [
457→            ...prev.messages,
458→            {
459→              id: nextId(),
460→              role: "system",
461→              content: "CLI session ended",
462→              timestamp: Date.now(),
463→            },
464→          ],
465→        }));
466→        return;
467→      }
468→
469→      // ── cli_connected: show system message ──
470→      if (data.type === "cli_connected") {
471→        updateAgent(data.agentId, (prev) => ({
472→          ...prev,
473→          messages: [
474→            ...prev.messages,
475→            {
476→              id: nextId(),
477→              role: "system",
478→              content: "CLI reconnected",
479→              timestamp: Date.now(),
480→            },
481→          ],
482→        }));
483→        return;
484→      }
485→
486→      // ── agent_list: reconcile sidebar state from server ──
487→      if (data.type === "agent_list") {
488→        const serverAgents = data.agents as AgentInfo[];
489→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
490→        setAgents((prev) => {
491→          const next = new Map(prev);
492→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
493→
494→          // Update or add agents from server
495→          for (const info of serverAgents) {
496→            const existing = next.get(info.agentId);
497→            if (existing) {
498→              next.set(info.agentId, {
499→                ...existing,
500→                status: info.status,
501→                tmuxSession: info.tmuxSession,
502→                label: info.label,
503→              });
504→            } else {
505→              next.set(info.agentId, {
506→                status: info.status,
507→                messages: [],
508→                rawMessages: [],
509→                label: info.label,
510→                tmuxSession: info.tmuxSession,
511→                createdAt: info.createdAt,
512→              });
513→            }
514→          }
515→
516→          // Remove agents no longer on the server
517→          for (const id of next.keys()) {
518→            if (!serverIds.has(id)) {
519→              next.delete(id);
520→            }
521→          }
522→
523→          return next;
524→        });
525→        setAgentOrder(serverAgents.map((a) => a.agentId));
526→        setInitialLoadDone(true);
527→
528→        // Auto-select the first agent on initial load when nothing is selected
529→        setActiveAgentId((prev) => {
530→          if (prev !== null) return prev;
531→          if (serverAgents.length === 0) return null;
532→          return serverAgents[0].agentId;
533→        });
534→        return;
535→      }
536→
537→      // ── spawned: auto-select the newly created agent ──
538→      if (data.type === "spawned") {
539→        setActiveAgentId(data.agentId);
540→        return;
541→      }
542→
543→      // ── status: update a specific agent's status ──
544→      if (data.type === "status") {
545→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
546→        return;
547→      }
548→
549→      // ── error: append to agent's message list ──
550→      if (data.type === "error") {
551→        sfxError();
552→        updateAgent(data.agentId, (prev) => ({
553→          ...prev,
554→          messages: [
555→            ...prev.messages,
556→            {
557→              id: nextId(),
558→              role: "system",
559→              content: `Error: ${data.error}`,
560→              timestamp: Date.now(),
561→            },
562→          ],
563→        }));
564→        // Track processed count for dedup
565→        processedCountRef.current.set(
566→          data.agentId,
567→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
568→        );
569→        return;
570→      }
571→
572→      // ── relay: append claude message to agent's history ──
573→      if (data.type === "relay") {
574→        const agentId = data.agentId;
575→        const rawMsg = data.message;
576→        const chatMsg = relayChatMessage(agentId, data);
577→
578→        // SFX: play a sound for each tool call in the message
579→        if (chatMsg?.toolCalls?.length) {
580→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
581→          const first = chatMsg.toolCalls.find((tc) => tc.name);
582→          if (first) sfxTool(first.name);
583→        }
584→
585→        // SFX: result done / error
586→        if (rawMsg.type === "result") {
587→          const result = rawMsg as ClaudeResult;
588→          if (result.is_error) sfxError();
589→          else sfxDone();
590→        }
591→
592→        // SFX: control request (tool approval / question)
593→        if (rawMsg.type === "control_request") {
594→          sfxQuestion();
595→        }
596→
597→        // SFX: session start
598→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
599→          sfxBegin();
600→        }
601→
602→        updateAgent(agentId, (prev) => ({
603→          ...prev,
604→          rawMessages: [...prev.rawMessages, rawMsg],
605→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
606→        }));
607→        if (chatMsg) {
608→          // Track processed count for dedup
609→          processedCountRef.current.set(
610→            agentId,
611→            (processedCountRef.current.get(agentId) ?? 0) + 1
612→          );
613→        }
614→        return;
615→      }
616→    };
617→  }, [updateAgent]);
618→
619→  useEffect(() => {
620→    closingRef.current = false;
621→    connect();
622→    return () => {
623→      closingRef.current = true;
624→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
625→      wsRef.current?.close();
626→    };
627→  }, [connect]);
628→
629→  const send = useCallback((data: object) => {
630→    if (wsRef.current?.readyState === WebSocket.OPEN) {
631→      wsRef.current.send(JSON.stringify(data));
632→    }
633→  }, []);
634→
635→  // Request history for the active agent if not already loaded.
636→  useEffect(() => {
637→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
638→    log("requesting history for", activeAgentId);
639→    send({ type: "request_history", agentId: activeAgentId });
640→  }, [activeAgentId, loadedAgents, send]);
641→
642→  const spawnAgent = useCallback(
643→    (prompt: string) => {
644→      send({ type: "spawn", prompt });
645→    },
646→    [send]
647→  );
648→
649→  const sendMessage = useCallback(
650→    (content: string) => {
651→      if (!activeAgentId) return;
652→      // Optimistically add user message to local state
653→      updateAgent(activeAgentId, (prev) => ({
654→        ...prev,
655→        messages: [
656→          ...prev.messages,
657→          {
658→            id: nextId(),
659→            role: "user",
660→            content,
661→            timestamp: Date.now(),
662→          },
663→        ],
664→      }));
665→      send({ type: "send_message", agentId: activeAgentId, content });
666→      sfxSend();
667→    },
668→    [send, activeAgentId, updateAgent]
669→  );
670→
671→  const respondToControl = useCallback(
672→    (requestId: string, allow: boolean) => {
673→      if (!activeAgentId) return;
674→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
675→      updateAgent(activeAgentId, (prev) => ({
676→        ...prev,
677→        messages: prev.messages.map((m) =>
678→          m.controlRequest?.id === requestId
679→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
680→            : m
681→        ),
682→      }));
683→    },
684→    [send, activeAgentId, updateAgent]
685→  );
686→
687→  /** Respond to an AskUserQuestion control request with the user's selections. */
688→  const respondToUserQuestion = useCallback(
689→    (requestId: string, answers: Record<string, string>) => {
690→      if (!activeAgentId) return;
691→      send({
692→        type: "control_response",
693→        agentId: activeAgentId,
694→        request_id: requestId,
695→        allow: true,
696→        answers,
697→      });
698→      updateAgent(activeAgentId, (prev) => ({
699→        ...prev,
700→        messages: prev.messages.map((m) =>
701→          m.userQuestion?.requestId === requestId
702→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
703→            : m
704→        ),
705→      }));
706→    },
707→    [send, activeAgentId, updateAgent]
708→  );
709→
710→  // ── Agent management actions ──────────────────────────────────────────────
711→
712→  const killAgent = useCallback(
713→    (agentId: string) => {
714→      send({ type: "kill_agent", agentId });
715→    },
716→    [send]
717→  );
718→
719→  const deleteAgent = useCallback(
720→    (agentId: string) => {
721→      send({ type: "delete_agent", agentId });
722→      // Deselect if we just deleted the active agent
723→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
724→    },
725→    [send]
726→  );
727→
728→  const renameAgent = useCallback(
729→    (agentId: string, label: string) => {
730→      send({ type: "rename_agent", agentId, label });
731→    },
732→    [send]
733→  );
734→
735→  const clearHistory = useCallback(
736→    (agentId: string) => {
737→      send({ type: "clear_history", agentId });
738→    },
739→    [send]
740→  );
741→
742→  // ── Task actions ──────────────────────────────────────────────────────────
743→
744→  const createTask = useCallback(
745→    (title: string, description: string, priority: TaskPriority) => {
746→      send({ type: "create_task", title, description, priority });
747→    },
748→    [send]
749→  );
750→
751→  const updateTask = useCallback(
752→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
753→      send({ type: "update_task", taskId, updates });
754→    },
755→    [send]
756→  );
757→
758→  const deleteTask = useCallback(
759→    (taskId: string) => {
760→      send({ type: "delete_task", taskId });
761→    },
762→    [send]
763→  );
764→
765→  const delegateTask = useCallback(
766→    (taskId: string) => {
767→      send({ type: "delegate_task", taskId });
768→    },
769→    [send]
770→  );
771→
772→  // ── Workspace actions ──────────────────────────────────────────────────────
773→
774→  const setActiveWorkspaceId = useCallback(
775→    (workspaceId: string | null) => {
776→      setActiveWorkspaceIdState(workspaceId);
777→      send({ type: "set_workspace", workspaceId });
778→    },
779→    [send]
780→  );
781→
782→  const createWorkspace = useCallback(
783→    (name: string, cwd: string) => {
784→      send({ type: "create_workspace", name, cwd });
785→    },
786→    [send]
787→  );
788→
789→  const renameWorkspace = useCallback(
790→    (workspaceId: string, name: string) => {
791→      send({ type: "rename_workspace", workspaceId, name });
792→    },
793→    [send]
794→  );
795→
796→  const deleteWorkspace = useCallback(
797→    (workspaceId: string) => {
798→      send({ type: "delete_workspace", workspaceId });
799→      setActiveWorkspaceIdState((prev) => (prev === workspaceId ? null : prev));
800→    },
801→    [send]
802→  );
803→
804→  const browseDirectory = useCallback(
805→    (path: string) => {
806→      send({ type: "browse_directory", path });
807→    },
808→    [send]
809→  );
810→
811→  // Derived values for the active agent
812→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
813→  const activeStatus = useMemo<AgentStatus>(
814→    () => activeAgent?.status ?? "idle",
815→    [activeAgent?.status]
816→  );
817→  const activeMessages = useMemo<ChatMessage[]>(
818→    () => activeAgent?.messages ?? [],
819→    [activeAgent?.messages]
820→  );
821→  const activeRawMessages = useMemo<ClaudeMessage[]>(
822→    () => activeAgent?.rawMessages ?? [],
823→    [activeAgent?.rawMessages]
824→  );
825→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
826→
827→  return {
828→    connected,
829→    initialLoadDone,
830→    historyLoading,
831→    agents,
832→    agentOrder,
833→    activeAgentId,
834→    setActiveAgentId,
835→    activeStatus,
836→    activeMessages,
837→    activeRawMessages,
838→    spawnAgent,
839→    sendMessage,
840→    respondToControl,
841→    respondToUserQuestion,
842→    killAgent,
843→    deleteAgent,
844→    renameAgent,
845→    clearHistory,
846→    tasks,
847→    createTask,
848→    updateTask,
849→    deleteTask,
850→    delegateTask,
851→    workspaces,
852→    activeWorkspaceId,
853→    setActiveWorkspaceId,
854→    createWorkspace,
855→    renameWorkspace,
856→    deleteWorkspace,
857→    browseDirectory,
858→    directoryListing,
859→  };
860→}
