   1→/**
   2→ * Standalone WebSocket relay server for the thos dashboard.
   3→ *
   4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
   5→ * `dev` script). It cannot be a Next.js API route because API routes don't
   6→ * support persistent WebSocket connections.
   7→ *
   8→ * ## Architecture
   9→ *
  10→ * Two WebSocket path families:
  11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
  12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
  13→ *
  14→ * The server supports multiple concurrent agents, each tracked in the
  15→ * `agents` Map keyed by a short random ID.
  16→ *
  17→ * ## Connection flow (browser)
  18→ *
  19→ * On browser connect, the server sends two small messages:
  20→ * 1. `agent_list`  — metadata for all agents (sidebar).
  21→ * 2. `task_list`   — all tasks.
  22→ *
  23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
  24→ * browser sends `{ type: "request_history", agentId }` when the user
  25→ * selects an agent, and the server responds with `message_history` for
  26→ * that single agent. This avoids sending megabytes of JSON on connect,
  27→ * which caused multi-minute loading times on mobile networks.
  28→ *
  29→ * Live messages for active agents are still broadcast to all browsers
  30→ * via `relay` messages in real time.
  31→ *
  32→ * ## Message flow (spawning)
  33→ *
  34→ * 1. Browser sends `{ type: "spawn", prompt }`.
  35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
  36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
  37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
  38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
  39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
  40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
  41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
  42→ *
  43→ * ## Resilience features
  44→ *
  45→ * - **Server-side message history** — every relay message is stored per-agent.
  46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
  47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
  48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
  49→ *   can reconnect to the new server if they retry their WebSocket connection.
  50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
  51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
  52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
  53→ */
  54→import { WebSocketServer, WebSocket } from "ws";
  55→import { execSync, spawn } from "child_process";
  56→import { randomBytes } from "crypto";
  57→import type { IncomingMessage } from "http";
  58→import { readdirSync, statSync, existsSync } from "fs";
  59→import { join, dirname, basename } from "path";
  60→import type {
  61→  BrowserMessage,
  62→  ClaudeMessage,
  63→  ServerMessage,
  64→  AgentStatus,
  65→  AgentInfo,
  66→  Task,
  67→  Workspace,
  68→  DirectoryEntry,
  69→} from "../lib/types";
  70→import { SessionStore, type PersistedAgent } from "./session-store";
  71→import { TaskStore } from "./task-store";
  72→import { WorkspaceStore } from "./workspace-store";
  73→
  74→const PORT = 9900;
  75→const TMUX_SESSION_PREFIX = "thos-agent";
  76→
  77→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
  78→function isAllowedIP(ip: string | undefined): boolean {
  79→  if (!ip) return false;
  80→  // Strip IPv6-mapped IPv4 prefix
  81→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
  82→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
  83→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
  84→  const parts = addr.split(".");
  85→  if (parts.length !== 4) return false;
  86→  const first = parseInt(parts[0], 10);
  87→  const second = parseInt(parts[1], 10);
  88→  return first === 100 && second >= 64 && second <= 127;
  89→}
  90→
  91→const wss = new WebSocketServer({
  92→  port: PORT,
  93→  verifyClient: (info: { req: { socket: { remoteAddress?: string } } }) => {
  94→    const ip = info.req.socket.remoteAddress;
  95→    const allowed = isAllowedIP(ip);
  96→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
  97→    return allowed;
  98→  },
  99→});
 100→const store = new SessionStore();
 101→
 102→// ── Multi-agent state ──────────────────────────────────────────────────────
 103→
 104→interface AgentState {
 105→  agentId: string;
 106→  claudeSocket: WebSocket | null;
 107→  tmuxSession: string | null;
 108→  pendingPrompt: string | null;
 109→  status: AgentStatus;
 110→  label: string;
 111→  createdAt: number;
 112→  /** Captured from system/init, used in subsequent user messages. */
 113→  sessionId: string | null;
 114→  /** Workspace this agent belongs to. */
 115→  workspaceId: string | null;
 116→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 117→  pendingControlRequests: Map<string, Record<string, unknown>>;
 118→  /** All messages sent to the browser for this agent (source of truth). */
 119→  messageHistory: ServerMessage[];
 120→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 121→  pendingMessages: string[];
 122→}
 123→
 124→const agents = new Map<string, AgentState>();
 125→const taskStore = new TaskStore();
 126→const tasks = new Map<string, Task>();
 127→const workspaceStore = new WorkspaceStore();
 128→const workspaces = new Map<string, Workspace>();
 129→
 130→/** All active browser connections (supports multiple tabs). */
 131→const browserSockets = new Set<WebSocket>();
 132→
 133→/** Per-browser workspace scope (null = show all). */
 134→const browserWorkspaceScope = new Map<WebSocket, string | null>();
 135→
 136→/** Generate a short random agent ID. */
 137→function newAgentId(): string {
 138→  return randomBytes(4).toString("hex");
 139→}
 140→
 141→// ── tmux helpers ───────────────────────────────────────────────────────────
 142→
 143→/** Return the set of currently alive tmux session names matching the thos prefix. */
 144→function listAliveTmuxSessions(): Set<string> {
 145→  try {
 146→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
 147→      encoding: "utf-8",
 148→    }).trim();
 149→    if (!output) return new Set();
 150→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
 151→  } catch {
 152→    return new Set();
 153→  }
 154→}
 155→
 156→// ── Persistence helpers ────────────────────────────────────────────────────
 157→
 158→/** Build a PersistedAgent snapshot from live state. */
 159→function toPersistedAgent(agent: AgentState): PersistedAgent {
 160→  return {
 161→    id: agent.agentId,
 162→    state: {
 163→      agentId: agent.agentId,
 164→      status: agent.status,
 165→      tmuxSession: agent.tmuxSession,
 166→      label: agent.label,
 167→      createdAt: agent.createdAt,
 168→      sessionId: agent.sessionId,
 169→      workspaceId: agent.workspaceId,
 170→    },
 171→    messageHistory: agent.messageHistory,
 172→  };
 173→}
 174→
 175→/**
 176→ * Compact a message history by deduplicating cumulative snapshots.
 177→ * Keeps only the last version of each assistant/user message ID.
 178→ * Called on restore to shrink legacy bloated histories.
 179→ */
 180→function compactHistory(history: ServerMessage[]): ServerMessage[] {
 181→  // Build a map of msgId → last index
 182→  const lastIndex = new Map<string, number>();
 183→  for (let i = 0; i < history.length; i++) {
 184→    const id = getRelayMessageId(history[i]);
 185→    if (id) lastIndex.set(id, i);
 186→  }
 187→  // Keep only messages that are either non-deduplicable or the last occurrence
 188→  return history.filter((msg, i) => {
 189→    const id = getRelayMessageId(msg);
 190→    if (!id) return true; // non-relay or no message ID — always keep
 191→    return lastIndex.get(id) === i;
 192→  });
 193→}
 194→
 195→/** Persist agent state (debounced — use for streaming events). */
 196→function persistAgent(agent: AgentState) {
 197→  store.save(toPersistedAgent(agent));
 198→}
 199→
 200→/** Persist agent state immediately (use for critical state changes). */
 201→function persistAgentSync(agent: AgentState) {
 202→  store.saveSync(toPersistedAgent(agent));
 203→}
 204→
 205→// ── Restore from disk on startup ───────────────────────────────────────────
 206→
 207→function restoreAgents() {
 208→  const persisted = store.loadAll();
 209→  const aliveSessions = listAliveTmuxSessions();
 210→
 211→  for (const p of persisted) {
 212→    const agent: AgentState = {
 213→      agentId: p.state.agentId,
 214→      claudeSocket: null,
 215→      tmuxSession: p.state.tmuxSession,
 216→      pendingPrompt: null,
 217→      status: p.state.status,
 218→      label: p.state.label,
 219→      createdAt: p.state.createdAt,
 220→      sessionId: p.state.sessionId,
 221→      workspaceId: p.state.workspaceId ?? null,
 222→      pendingControlRequests: new Map(),
 223→      messageHistory: compactHistory(p.messageHistory),
 224→      pendingMessages: [],
 225→    };
 226→
 227→    // Determine status for agents that were active when the server last ran
 228→    if (agent.status !== "done" && agent.status !== "error") {
 229→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
 230→      if (tmuxAlive) {
 231→        // tmux session still alive — CLI may reconnect to this server
 232→        agent.status = "disconnected";
 233→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
 234→      } else {
 235→        // tmux session gone — agent is archived
 236→        agent.status = "done";
 237→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
 238→      }
 239→    }
 240→
 241→    agents.set(agent.agentId, agent);
 242→    const originalCount = p.messageHistory.length;
 243→    const compactedCount = agent.messageHistory.length;
 244→    const saved = originalCount - compactedCount;
 245→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
 246→
 247→    // Persist compacted history back to disk
 248→    if (saved > 0) {
 249→      persistAgentSync(agent);
 250→    }
 251→  }
 252→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
 253→}
 254→
 255→restoreAgents();
 256→
 257→// ── Task restore + helpers ────────────────────────────────────────────────
 258→
 259→function restoreTasks() {
 260→  const persisted = taskStore.loadAll();
 261→  for (const t of persisted) {
 262→    tasks.set(t.id, t);
 263→  }
 264→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
 265→}
 266→
 267→restoreTasks();
 268→
 269→// ── Workspace restore + helpers ──────────────────────────────────────────
 270→
 271→function restoreWorkspaces() {
 272→  const persisted = workspaceStore.loadAll();
 273→  for (const w of persisted) {
 274→    workspaces.set(w.id, w);
 275→  }
 276→  console.log(`[restore] loaded ${persisted.length} workspaces from disk`);
 277→}
 278→
 279→restoreWorkspaces();
 280→
 281→/** Persist all workspaces to disk (sync). */
 282→function persistWorkspaces() {
 283→  workspaceStore.saveSync(Array.from(workspaces.values()));
 284→}
 285→
 286→/** Send the full workspace list to all browsers. */
 287→function broadcastWorkspaceList() {
 288→  const payload = JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) });
 289→  for (const ws of browserSockets) {
 290→    if (ws.readyState === WebSocket.OPEN) {
 291→      ws.send(payload);
 292→    }
 293→  }
 294→}
 295→
 296→/** Build the full task list sorted by creation time (newest first), optionally filtered by workspace. */
 297→function buildTaskList(workspaceId?: string | null): Task[] {
 298→  let list = Array.from(tasks.values());
 299→  if (workspaceId !== undefined && workspaceId !== null) {
 300→    list = list.filter((t) => t.workspaceId === workspaceId);
 301→  }
 302→  return list.sort((a, b) => b.createdAt - a.createdAt);
 303→}
 304→
 305→/** Send the full task list to all browsers (scoped per-browser workspace). */
 306→function broadcastTaskList() {
 307→  for (const ws of browserSockets) {
 308→    if (ws.readyState !== WebSocket.OPEN) continue;
 309→    const scope = browserWorkspaceScope.get(ws) ?? null;
 310→    ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 311→  }
 312→}
 313→
 314→/** Persist all tasks to disk (sync). */
 315→function persistTasks() {
 316→  taskStore.saveSync(Array.from(tasks.values()));
 317→}
 318→
 319→// ── Helpers ────────────────────────────────────────────────────────────────
 320→
 321→/** Send a JSON message to all connected browsers. */
 322→function sendToBrowser(msg: ServerMessage) {
 323→  const payload = JSON.stringify(msg);
 324→  for (const ws of browserSockets) {
 325→    if (ws.readyState === WebSocket.OPEN) {
 326→      ws.send(payload);
 327→    }
 328→  }
 329→}
 330→
 331→/** Build a snapshot of all agents for the sidebar, optionally filtered by workspace. */
 332→function buildAgentList(workspaceId?: string | null): AgentInfo[] {
 333→  let list = Array.from(agents.values());
 334→  if (workspaceId !== undefined && workspaceId !== null) {
 335→    list = list.filter((a) => a.workspaceId === workspaceId);
 336→  }
 337→  return list.map((a) => ({
 338→    agentId: a.agentId,
 339→    status: a.status,
 340→    tmuxSession: a.tmuxSession,
 341→    label: a.label,
 342→    createdAt: a.createdAt,
 343→    workspaceId: a.workspaceId,
 344→  }));
 345→}
 346→
 347→/** Send the full agent list to all browsers (scoped per-browser workspace). */
 348→function broadcastAgentList() {
 349→  for (const ws of browserSockets) {
 350→    if (ws.readyState !== WebSocket.OPEN) continue;
 351→    const scope = browserWorkspaceScope.get(ws) ?? null;
 352→    ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 353→  }
 354→}
 355→
 356→/** Update an agent's status, notify browsers, broadcast list, and persist. */
 357→function setAgentStatus(agentId: string, status: AgentStatus) {
 358→  const agent = agents.get(agentId);
 359→  if (!agent) return;
 360→  agent.status = status;
 361→  sendToBrowser({ type: "status", agentId, status });
 362→  broadcastAgentList();
 363→  persistAgentSync(agent);
 364→}
 365→
 366→/**
 367→ * Extract a stable dedup key from a relay message, if present.
 368→ *
 369→ * Claude NDJSON sends cumulative snapshots for two message types:
 370→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 371→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 372→ *
 373→ * Additionally, one-per-session messages are deduplicated by session_id:
 374→ * - `system/init` — keyed by `init:<session_id>`
 375→ * - `result` — keyed by `result:<session_id>`
 376→ *
 377→ * We deduplicate by replacing the previous snapshot in `messageHistory`
 378→ * instead of appending, reducing storage from O(n²) to O(n).
 379→ */
 380→function getRelayMessageId(msg: ServerMessage): string | null {
 381→  if (msg.type !== "relay") return null;
 382→  const inner = msg.message;
 383→  if (inner.type === "assistant") {
 384→    return (inner as { message?: { id?: string } }).message?.id ?? null;
 385→  }
 386→  if (inner.type === "user") {
 387→    return (inner as { uuid?: string }).uuid ?? null;
 388→  }
 389→  // Dedup system/init and result by session_id so they don't stack on reload
 390→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
 391→    const sid = (inner as { session_id?: string }).session_id;
 392→    return sid ? `init:${sid}` : null;
 393→  }
 394→  if (inner.type === "result") {
 395→    const sid = (inner as { session_id?: string }).session_id;
 396→    return sid ? `result:${sid}` : null;
 397→  }
 398→  return null;
 399→}
 400→
 401→/**
 402→ * Record a message in the agent's history and send to all browsers.
 403→ *
 404→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
 405→ * previous snapshot with the same message ID instead of appending. This keeps
 406→ * only the final version of each message, dramatically reducing file sizes
 407→ * (e.g. 38 MB → ~1 MB for a typical session).
 408→ */
 409→function recordAndSend(agentId: string, msg: ServerMessage) {
 410→  const agent = agents.get(agentId);
 411→  if (agent) {
 412→    const msgId = getRelayMessageId(msg);
 413→    if (msgId) {
 414→      // Replace previous snapshot with same message ID (search from end for speed)
 415→      let replaced = false;
 416→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
 417→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
 418→          agent.messageHistory[i] = msg;
 419→          replaced = true;
 420→          break;
 421→        }
 422→      }
 423→      if (!replaced) {
 424→        agent.messageHistory.push(msg);
 425→      }
 426→    } else {
 427→      agent.messageHistory.push(msg);
 428→    }
 429→    persistAgent(agent); // debounced — streaming messages come fast
 430→  }
 431→  sendToBrowser(msg);
 432→}
 433→
 434→// ── Agent lifecycle ────────────────────────────────────────────────────────
 435→
 436→/**
 437→ * Stop a running agent by killing its tmux session and closing the CLI socket.
 438→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
 439→ */
 440→function stopAgent(agentId: string) {
 441→  const agent = agents.get(agentId);
 442→  if (!agent) return;
 443→
 444→  if (agent.tmuxSession) {
 445→    try {
 446→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 447→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
 448→    } catch {
 449→      // Session may already be dead
 450→    }
 451→  }
 452→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 453→    agent.claudeSocket.close();
 454→  }
 455→  agent.claudeSocket = null;
 456→  setAgentStatus(agentId, "done");
 457→}
 458→
 459→/**
 460→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
 461→ */
 462→function deleteAgent(agentId: string) {
 463→  const agent = agents.get(agentId);
 464→  if (!agent) return;
 465→
 466→  if (agent.tmuxSession) {
 467→    try {
 468→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 469→    } catch {}
 470→  }
 471→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 472→    agent.claudeSocket.close();
 473→  }
 474→  agents.delete(agentId);
 475→  store.remove(agentId);
 476→  broadcastAgentList();
 477→}
 478→
 479→/**
 480→ * Spawn a new Claude CLI process inside a tmux session.
 481→ *
 482→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
 483→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
 484→ * If `workspaceId` is provided, the tmux session starts in that workspace's cwd.
 485→ */
 486→function spawnClaude(prompt: string, workspaceId?: string | null): string {
 487→  const agentId = newAgentId();
 488→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
 489→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
 490→
 491→  const agent: AgentState = {
 492→    agentId,
 493→    claudeSocket: null,
 494→    tmuxSession: null,
 495→    pendingPrompt: prompt,
 496→    status: "spawning",
 497→    label,
 498→    createdAt: Date.now(),
 499→    sessionId: null,
 500→    workspaceId: workspaceId ?? null,
 501→    pendingControlRequests: new Map(),
 502→    messageHistory: [],
 503→    pendingMessages: [],
 504→  };
 505→  agents.set(agentId, agent);
 506→
 507→  // Notify browsers
 508→  sendToBrowser({ type: "spawned", agentId });
 509→  broadcastAgentList();
 510→  persistAgentSync(agent);
 511→
 512→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
 513→  // tmux new-session runs detached (-d) so spawn() returns immediately.
 514→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
 515→
 516→  // If the agent belongs to a workspace, start tmux in that workspace's cwd
 517→  const workspace = workspaceId ? workspaces.get(workspaceId) : null;
 518→  const tmuxArgs = ["new-session", "-d", "-s", sessionName];
 519→  if (workspace) {
 520→    tmuxArgs.push("-c", workspace.cwd);
 521→  }
 522→  tmuxArgs.push("bash", "-c", claudeCmd);
 523→
 524→  const tmux = spawn("tmux", tmuxArgs, {
 525→    stdio: "ignore",
 526→  });
 527→
 528→  tmux.on("error", (err) => {
 529→    console.error("[tmux spawn error]", err);
 530→    setAgentStatus(agentId, "error");
 531→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
 532→  });
 533→
 534→  tmux.on("exit", (code) => {
 535→    if (code !== 0) {
 536→      console.error(`[tmux] new-session exited with code ${code}`);
 537→      setAgentStatus(agentId, "error");
 538→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
 539→      return;
 540→    }
 541→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
 542→    agent.tmuxSession = sessionName;
 543→    broadcastAgentList();
 544→    persistAgentSync(agent);
 545→  });
 546→
 547→  return agentId;
 548→}
 549→
 550→// ── Message handlers ───────────────────────────────────────────────────────
 551→
 552→/**
 553→ * Process an incoming NDJSON message from a specific Claude CLI.
 554→ *
 555→ * Status flow matches the Companion protocol:
 556→ * - hook_response → send pending prompt → "thinking"
 557→ * - system/init   → "connected" + capture session_id
 558→ * - assistant      → "thinking"
 559→ * - result         → "connected" (CLI stays alive for multi-turn)
 560→ * - CLI disconnect → "done" (handled in connection close handler)
 561→ */
 562→function handleClaudeMessage(agentId: string, raw: string) {
 563→  const agent = agents.get(agentId);
 564→  if (!agent) return;
 565→
 566→  let msg: ClaudeMessage;
 567→  try {
 568→    msg = JSON.parse(raw);
 569→  } catch {
 570→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
 571→    return;
 572→  }
 573→
 574→  // Silently ignore keep_alive messages
 575→  if (msg.type === "keep_alive") return;
 576→
 577→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
 578→
 579→  // After hook_response, send the pending prompt
 580→  if (
 581→    msg.type === "system" &&
 582→    (msg as { subtype?: string }).subtype === "hook_response" &&
 583→    agent.pendingPrompt &&
 584→    agent.claudeSocket?.readyState === WebSocket.OPEN
 585→  ) {
 586→    const promptContent = agent.pendingPrompt;
 587→    const userMsg = JSON.stringify({
 588→      type: "user",
 589→      message: { role: "user", content: promptContent },
 590→      parent_tool_use_id: null,
 591→      session_id: agent.sessionId ?? "",
 592→    });
 593→    console.log(`[server → claude:${agentId}]`, userMsg);
 594→    agent.claudeSocket.send(userMsg + "\n");
 595→    agent.pendingPrompt = null;
 596→    setAgentStatus(agentId, "thinking");
 597→
 598→    // Record the initial user message so it appears in chat and persists across reloads
 599→    recordAndSend(agentId, {
 600→      type: "relay",
 601→      agentId,
 602→      message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
 603→    });
 604→  }
 605→
 606→  // Track status based on message type
 607→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 608→    // Capture session_id for subsequent user messages
 609→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
 610→    setAgentStatus(agentId, "connected");
 611→  } else if (msg.type === "assistant") {
 612→    setAgentStatus(agentId, "thinking");
 613→  } else if (msg.type === "result") {
 614→    // CLI stays alive after result — ready for the next turn.
 615→    // Status only goes to "done" when the CLI WebSocket actually closes.
 616→    setAgentStatus(agentId, "connected");
 617→  }
 618→
 619→  // Store control_request inputs for building proper responses later
 620→  if (msg.type === "control_request") {
 621→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
 622→    if (cr.request_id && cr.request?.input) {
 623→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
 624→    }
 625→  }
 626→
 627→  // Record in history and relay to browsers
 628→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
 629→}
 630→
 631→/**
 632→ * Process an incoming JSON message from the browser.
 633→ * - `spawn`: create a new agent (does NOT kill others).
 634→ * - `send_message`: forward a follow-up user message to the specified agent.
 635→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
 636→ * - `kill_agent`: stop the CLI and tmux session.
 637→ * - `delete_agent`: permanently remove an agent.
 638→ * - `rename_agent`: update an agent's label.
 639→ * - `clear_history`: wipe an agent's message history.
 640→ * - `request_history`: send message history for a single agent (lazy loading).
 641→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
 642→ */
 643→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
 644→  let msg: BrowserMessage;
 645→  try {
 646→    msg = JSON.parse(raw);
 647→  } catch {
 648→    console.error("[browser] invalid JSON:", raw);
 649→    return;
 650→  }
 651→
 652→  console.log("[browser →]", msg.type);
 653→
 654→  switch (msg.type) {
 655→    case "spawn": {
 656→      const scope = browserWorkspaceScope.get(senderWs) ?? msg.workspaceId ?? null;
 657→      spawnClaude(msg.prompt, scope);
 658→      break;
 659→    }
 660→
 661→    case "send_message": {
 662→      const agent = agents.get(msg.agentId);
 663→      if (!agent) {
 664→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
 665→        break;
 666→      }
 667→
 668→      // Record the user message in history so it persists across reloads.
 669→      // Do NOT broadcast — the sending browser already has it optimistically,
 670→      // and other browsers will get it when they request_history.
 671→      agent.messageHistory.push({
 672→        type: "relay",
 673→        agentId: msg.agentId,
 674→        message: { type: "user", message: { role: "user", content: msg.content } },
 675→      } as ServerMessage);
 676→      persistAgent(agent);
 677→
 678→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 679→        const userMsg = JSON.stringify({
 680→          type: "user",
 681→          message: { role: "user", content: msg.content },
 682→          parent_tool_use_id: null,
 683→          session_id: agent.sessionId ?? "",
 684→        });
 685→        agent.claudeSocket.send(userMsg + "\n");
 686→        setAgentStatus(msg.agentId, "thinking");
 687→      } else {
 688→        // Queue message for delivery when CLI reconnects
 689→        const userMsg = JSON.stringify({
 690→          type: "user",
 691→          message: { role: "user", content: msg.content },
 692→          parent_tool_use_id: null,
 693→          session_id: agent.sessionId ?? "",
 694→        });
 695→        agent.pendingMessages.push(userMsg);
 696→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
 697→        persistAgentSync(agent);
 698→      }
 699→      break;
 700→    }
 701→
 702→    case "control_response": {
 703→      const agent = agents.get(msg.agentId);
 704→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
 705→        // Retrieve the original tool input to include as updatedInput (required by protocol)
 706→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
 707→        agent.pendingControlRequests.delete(msg.request_id);
 708→
 709→        // If the browser sent answers (from AskUserQuestion), merge them into the input
 710→        const answers = (msg as { answers?: Record<string, string> }).answers;
 711→        const updatedInput = answers
 712→          ? { ...originalInput, answers }
 713→          : originalInput;
 714→
 715→        const response = JSON.stringify({
 716→          type: "control_response",
 717→          response: {
 718→            subtype: "success",
 719→            request_id: msg.request_id,
 720→            response: msg.allow
 721→              ? { behavior: "allow", updatedInput }
 722→              : { behavior: "deny", message: "Denied by user" },
 723→          },
 724→        });
 725→        agent.claudeSocket.send(response + "\n");
 726→      }
 727→      break;
 728→    }
 729→
 730→    case "kill_agent":
 731→      stopAgent(msg.agentId);
 732→      break;
 733→
 734→    case "delete_agent":
 735→      deleteAgent(msg.agentId);
 736→      break;
 737→
 738→    case "rename_agent": {
 739→      const agent = agents.get(msg.agentId);
 740→      if (!agent) break;
 741→      agent.label = msg.label;
 742→      broadcastAgentList();
 743→      persistAgentSync(agent);
 744→      break;
 745→    }
 746→
 747→    case "clear_history": {
 748→      const agent = agents.get(msg.agentId);
 749→      if (!agent) break;
 750→      agent.messageHistory = [];
 751→      persistAgentSync(agent);
 752→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
 753→      break;
 754→    }
 755→
 756→    case "request_history": {
 757→      console.log(`[browser] request_history for ${msg.agentId}`);
 758→      sendHistoryToSocket(senderWs, msg.agentId);
 759→      break;
 760→    }
 761→
 762→    case "create_task": {
 763→      const taskId = randomBytes(4).toString("hex");
 764→      const task: Task = {
 765→        id: taskId,
 766→        title: msg.title,
 767→        description: msg.description,
 768→        status: "todo",
 769→        priority: msg.priority,
 770→        agentId: null,
 771→        workspaceId: browserWorkspaceScope.get(senderWs) ?? null,
 772→        createdAt: Date.now(),
 773→        updatedAt: Date.now(),
 774→      };
 775→      tasks.set(taskId, task);
 776→      persistTasks();
 777→      broadcastTaskList();
 778→      break;
 779→    }
 780→
 781→    case "update_task": {
 782→      const task = tasks.get(msg.taskId);
 783→      if (!task) break;
 784→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
 785→      persistTasks();
 786→      broadcastTaskList();
 787→
 788→      // Archive the linked agent when a task is marked as done
 789→      if (task.status === "done" && task.agentId) {
 790→        const linkedAgent = agents.get(task.agentId);
 791→        if (linkedAgent && linkedAgent.status !== "done") {
 792→          stopAgent(task.agentId);
 793→        }
 794→      }
 795→      break;
 796→    }
 797→
 798→    case "delete_task": {
 799→      tasks.delete(msg.taskId);
 800→      persistTasks();
 801→      broadcastTaskList();
 802→      break;
 803→    }
 804→
 805→    case "delegate_task": {
 806→      const task = tasks.get(msg.taskId);
 807→      if (!task) break;
 808→      const prompt = `Task: ${task.title}\n\n${task.description}`;
 809→      const agentId = spawnClaude(prompt, task.workspaceId);
 810→      task.agentId = agentId;
 811→      task.status = "in-progress";
 812→      task.updatedAt = Date.now();
 813→      persistTasks();
 814→      broadcastTaskList();
 815→      break;
 816→    }
 817→
 818→    // ── Workspace messages ──────────────────────────────────────────────
 819→
 820→    case "set_workspace": {
 821→      browserWorkspaceScope.set(senderWs, msg.workspaceId);
 822→      // Re-send scoped agent list and task list to this browser
 823→      const scope = msg.workspaceId;
 824→      senderWs.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 825→      senderWs.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 826→      break;
 827→    }
 828→
 829→    case "create_workspace": {
 830→      const id = randomBytes(4).toString("hex");
 831→      const workspace: Workspace = {
 832→        id,
 833→        name: msg.name,
 834→        cwd: msg.cwd,
 835→        createdAt: Date.now(),
 836→      };
 837→      workspaces.set(id, workspace);
 838→      persistWorkspaces();
 839→      broadcastWorkspaceList();
 840→      break;
 841→    }
 842→
 843→    case "rename_workspace": {
 844→      const workspace = workspaces.get(msg.workspaceId);
 845→      if (!workspace) break;
 846→      workspace.name = msg.name;
 847→      persistWorkspaces();
 848→      broadcastWorkspaceList();
 849→      break;
 850→    }
 851→
 852→    case "delete_workspace": {
 853→      workspaces.delete(msg.workspaceId);
 854→      // Unlink agents and tasks from the deleted workspace
 855→      for (const agent of agents.values()) {
 856→        if (agent.workspaceId === msg.workspaceId) {
 857→          agent.workspaceId = null;
 858→          persistAgentSync(agent);
 859→        }
 860→      }
 861→      for (const task of tasks.values()) {
 862→        if (task.workspaceId === msg.workspaceId) {
 863→          task.workspaceId = null;
 864→        }
 865→      }
 866→      persistTasks();
 867→      persistWorkspaces();
 868→      broadcastWorkspaceList();
 869→      broadcastAgentList();
 870→      broadcastTaskList();
 871→      break;
 872→    }
 873→
 874→    case "browse_directory": {
 875→      const dirPath = msg.path;
 876→      try {
 877→        if (!existsSync(dirPath)) {
 878→          senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 879→          break;
 880→        }
 881→        const entries: DirectoryEntry[] = [];
 882→        // Add parent directory entry
 883→        const parent = dirname(dirPath);
 884→        if (parent !== dirPath) {
 885→          entries.push({ name: "..", path: parent });
 886→        }
 887→        // List subdirectories only
 888→        const items = readdirSync(dirPath);
 889→        for (const item of items) {
 890→          if (item.startsWith(".")) continue; // skip dotfiles
 891→          const fullPath = join(dirPath, item);
 892→          try {
 893→            const stat = statSync(fullPath);
 894→            if (stat.isDirectory()) {
 895→              entries.push({ name: item, path: fullPath });
 896→            }
 897→          } catch {
 898→            // skip inaccessible entries
 899→          }
 900→        }
 901→        // Sort: ".." first, then alphabetical
 902→        entries.sort((a, b) => {
 903→          if (a.name === "..") return -1;
 904→          if (b.name === "..") return 1;
 905→          return a.name.localeCompare(b.name);
 906→        });
 907→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries }));
 908→      } catch (err) {
 909→        console.error(`[browse_directory] error reading ${dirPath}:`, err);
 910→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 911→      }
 912→      break;
 913→    }
 914→  }
 915→}
 916→
 917→// ── Send message history to a single browser socket ────────────────────────
 918→
 919→/** Send initial state (workspaces, agent list, tasks) to a newly connected browser. */
 920→function sendFullStateToSocket(ws: WebSocket) {
 921→  if (ws.readyState !== WebSocket.OPEN) return;
 922→
 923→  // Workspace list
 924→  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));
 925→
 926→  // Agent list (sidebar metadata) — scoped if browser has a workspace set
 927→  const scope = browserWorkspaceScope.get(ws) ?? null;
 928→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 929→
 930→  // Task list — scoped if browser has a workspace set
 931→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 932→}
 933→
 934→/** Send message history for a single agent to a specific browser socket. */
 935→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
 936→  const agent = agents.get(agentId);
 937→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
 938→  ws.send(
 939→    JSON.stringify({
 940→      type: "message_history",
 941→      agentId: agent.agentId,
 942→      messages: agent.messageHistory,
 943→    })
 944→  );
 945→}
 946→
 947→// ── Connection handler — route by URL path ────────────────────────────────
 948→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
 949→  const path = req.url ?? "/";
 950→  console.log(`[ws connected] path=${path}`);
 951→
 952→  if (path === "/browser") {
 953→    // Send full state BEFORE adding to browserSockets so that live
 954→    // relay broadcasts don't interleave with the history replay.
 955→    sendFullStateToSocket(ws);
 956→    browserSockets.add(ws);
 957→
 958→    ws.on("message", (data) => {
 959→      handleBrowserMessage(data.toString(), ws);
 960→    });
 961→
 962→    ws.on("close", () => {
 963→      console.log("[browser disconnected]");
 964→      browserSockets.delete(ws);
 965→      browserWorkspaceScope.delete(ws);
 966→      // Do NOT kill agents — keep them alive for reconnect
 967→    });
 968→  } else if (path.startsWith("/claude/")) {
 969→    // Parse agentId from /claude/<agentId>
 970→    const agentId = path.slice("/claude/".length);
 971→    const agent = agents.get(agentId);
 972→
 973→    if (!agent) {
 974→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
 975→      ws.close();
 976→      return;
 977→    }
 978→
 979→    agent.claudeSocket = ws;
 980→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
 981→
 982→    // Notify browsers that CLI is connected
 983→    sendToBrowser({ type: "cli_connected", agentId });
 984→
 985→    // Flush any pending messages queued while CLI was disconnected
 986→    if (agent.pendingMessages.length > 0) {
 987→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
 988→      for (const queued of agent.pendingMessages) {
 989→        ws.send(queued + "\n");
 990→      }
 991→      agent.pendingMessages = [];
 992→      persistAgentSync(agent);
 993→    }
 994→
 995→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
 996→    // server to send the first user message rather than emitting
 997→    // hook_started/hook_response on connect.
 998→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
